    test('cancel cannot publish and draft mode never authorizes a delivery',function()use($pdo,$u,$batch,$cfg,$image){$a=ideaStart($pdo,$u,['batch_id'=>$batch['id'],'idea_index'=>1,'mode'=>'draft']);ideaCancel($pdo,$u,$a['id']);imageAiRun($pdo,$cfg,$image);ideaRunDue($pdo);expect(opsOne($pdo,'SELECT status FROM idea_runs WHERE id=?',[$a['id']])['status']==='cancelled','cancelled');$b=ideaStart($pdo,$u,['batch_id'=>$batch['id'],'idea_index'=>2,'mode'=>'draft']);imageAiRun($pdo,$cfg,$image);ideaRunDue($pdo);$r=opsOne($pdo,'SELECT * FROM idea_runs WHERE id=?',[$b['id']]);expect(socialRow($pdo,$u,(int)$r['post_id'])['status']==='draft','draft published');});
    test('connection changes keep generated result private',function()use($pdo,$u,$batch,$cfg,$image,$input){$r=ideaStart($pdo,$u,array_merge($input,['idea_index'=>3]));opsExec($pdo,"UPDATE aulieata_instagram_connections SET check_status='invalid' WHERE user_id=?",[$u]);imageAiRun($pdo,$cfg,$image);ideaRunDue($pdo);$r=opsOne($pdo,'SELECT * FROM idea_runs WHERE id=?',[$r['id']]);expect($r['status']==='failed'&&socialRow($pdo,$u,(int)$r['post_id'])['status']==='draft','changed account used');});
