    opsSaveSettings($pdo,$u,['bot_mode'=>'free','orders_enabled'=>true,'bot_collect_contact'=>true]);$chat='90011001';
    test('multi-item checkout collects customer data and requires final confirmation once',function()use($pdo,$u,$owner,$chat){$r=opsBotHandle($pdo,$owner,$chat,'Заказ: Латте 2; Круассан 1',[]);expect(str_contains($r,'3 100,00')&&str_contains($r,'имя'),'cart quote');expect(!opsOne($pdo,'SELECT id FROM ops_orders WHERE user_id=?',[$u]),'premature order');opsBotHandle($pdo,$owner,$chat,'Алимжан',[]);opsBotHandle($pdo,$owner,$chat,'Пропустить',[]);$r=opsBotHandle($pdo,$owner,$chat,'В 18:00',[]);expect(str_contains($r,'Подтверждаю'),'final confirmation');opsBotHandle($pdo,$owner,$chat,'Подтверждаю',[]);opsBotHandle($pdo,$owner,$chat,'Подтверждаю',[]);$rows=opsAll($pdo,'SELECT payload FROM ops_orders WHERE user_id=?',[$u]);expect(count($rows)===1,'duplicate order');$q=json_decode($rows[0]['payload'],true);expect($q['client']==='Алимжан'&&$q['phone']===''&&$q['pickup_at']==='В 18:00','details lost');});
