    test('free appointment wizard checks actual slots and double booking on confirmation',function()use($pdo,$u,$owner){$s=catalogFixture($u,'Консультация',1000,['kind'=>'service','duration_minutes'=>30]);$hours=[];for($i=1;$i<=7;$i++)$hours[$i]=['enabled'=>true,'start'=>'09:00','end'=>'17:00'];opsSaveResource($pdo,$u,0,['name'=>'Специалист','hours'=>$hours,'service_ids'=>[$s]]);opsSaveSettings($pdo,$u,['bookings_enabled'=>true]);$chat='90011003';$r=opsBotHandle($pdo,$owner,$chat,'Записаться',[]);expect(str_contains($r,'Консультация'),'services');opsBotHandle($pdo,$owner,$chat,'1',[]);opsBotHandle($pdo,$owner,$chat,'1',[]);$date=(new DateTimeImmutable('tomorrow',new DateTimeZone('Asia/Qyzylorda')))->format('Y-m-d');$r=opsBotHandle($pdo,$owner,$chat,$date,[]);expect(str_contains($r,'09:00'),'slots');$r=opsBotHandle($pdo,$owner,$chat,'09:00',[]);expect(str_contains($r,'Подтверждаю'),'booking quote');opsBotHandle($pdo,$owner,$chat,'Подтверждаю',[]);expect((int)opsOne($pdo,'SELECT COUNT(*) n FROM ops_appointments WHERE user_id=?',[$u])['n']===1,'booking not saved');});
    test('cloud conversation uses public data only, rejects foreign actions and never falls back to paid AI',function()use($pdo,$u,$other,$owner,$cfg,$foreign){opsSaveSettings($pdo,$u,['bot_mode'=>'cloud']);opsRecord($pdo,$u,'knowledge',['name'=>'График работы','text'=>'PRIVATE_SECRET','audience'=>'internal']);$config=$cfg;$config['_cloud_request']=function($account,$token,$body){expect(!str_contains(opsJson($body),'PRIVATE_SECRET'),'private leak');return ['intent'=>'question','answer'=>'Уточните предпочтения, пожалуйста.'];};$r=opsBotHandle($pdo,$owner,'90011004','Посоветуйте что-нибудь интересное для встречи',$config);expect(str_contains($r,'предпочтения'),'cloud not used');$config['_cloud_request']=fn()=>['intent'=>'order','items'=>[['item_id'=>$foreign,'quantity'=>1]]];refuses(fn()=>opsBotHandle($pdo,$owner,'90011005','Оформите выбранный вариант',$config));$config['_cloud_request']=fn()=>throw new RuntimeException('quota');$r=opsBotHandle($pdo,$owner,'90011004','Расскажите поподробнее о вариантах',$config);expect(str_contains($r,'Уточните'),'free fallback');});
